* { box-sizing: border-box; }

body {
     margin: 0;
     padding: 32px 16px;
     font-family: Georgia, "Times New Roman", serif;
     background: #ffffff;
     display: flex;
     justify-content: center;
}

.bai-viet {
     width: min(880px, 100%);
     display: grid;
     grid-template-columns: 300px 1fr;
     gap: 28px;
     align-items: start;
}

.bai-viet img {
     width: 100%;
     border-radius: 8px;
     box-shadow: 0 8px 20px rgba(0, 0, 0, 0.2);

     display: block;
}

.bai-viet h1 {
     margin: 0 0 16px;
     color: #C9A227;
     font-size: 28px;
     text-shadow: 1px 1px 0 #ffffff, 2px 2px 4px rgba(0, 0, 0, 0.25);
}

.noi-dung {
     border: 2px dashed #E07B00;
     border-radius: 8px;
     padding: 20px;
}

.noi-dung p {
     margin: 0 0 14px;
     line-height: 1.85;
     text-align: justify;
}

.noi-dung p:last-child { margin-bottom: 0; }

.nhan-do {
     color: #C62828;
     font-weight: 700;
}

@media (max-width: 680px) {
     .bai-viet { grid-template-columns: 1fr; }
}
